        // Waits until the cutscene clock reaches the given millisecond mark.
        private static void WaitForCutsceneTime(int ms)
        {
            while (Globals.cutscene_time < ms) {
                Scm.Wait(0);
                Globals.cutscene_time = Scm.GetCutsceneTime();
            }
        }
